def build():
    for slug, (title, body) in PAGES.items():
        out = ROOT/slug/'index.html'
        out.parent.mkdir(exist_ok=True)
        out.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — EvolveTech</title><meta name="description" content="{escape(title)} for EvolveTech’s independent software projects."><link rel="canonical" href="https://www.evolvetech.dev/{slug}/"><link rel="stylesheet" href="/assets/v2/style.css"><script src="/assets/v2/theme.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell"><a class="brand" href="/">EvolveTech</a></div></header><main class="shell prose legal-page" id="main"><h1>{escape(title)}</h1>{body}</main></body></html>''')
    for page in ROOT.rglob('*.html'):
        rel = page.relative_to(ROOT).as_posix()
        if rel.startswith(('play/evolve-hosting/example/', 'play/evolve-llm/preview/')):
            continue
        s = page.read_text()
        if '</body>' not in s or '</head>' not in s:
            continue
        if 'class="evolve-legal-nav"' not in s:
            s = s.replace('</body>', NAV+'\n</body>', 1)
        if STYLE not in s:
            s = s.replace('</head>', STYLE+'\n</head>', 1)
        page.write_text(s)
        # Disclose the site-specific overlay and keep published file hashes accurate.
        manifest = page.parent/'BUILD.json'
        if manifest.exists():
            data = json.loads(manifest.read_text())
            data['site_overlay'] = {'tool': 'tools/build_legal.py', 'purpose': 'Privacy, use, reporting and security navigation'}
            if isinstance(data.get('files_sha256'), dict) and page.name in data['files_sha256']:
                data['files_sha256'][page.name] = hashlib.sha256(page.read_bytes()).hexdigest()
            manifest.write_text(json.dumps(data, indent=2)+'\n')

if __name__ == '__main__':
    build()
